export const MODULE1_RULES: GrammarRule[] = [
  { id: '30000000-0000-0000-0000-000000000001', slug: 'subject-pronouns', title: 'Subject pronouns', category: 'Syntax', summary: 'French verb forms change with the subject: je, tu, il/elle/on, nous, vous, ils/elles.', full_explanation: 'A subject pronoun tells us who performs the action. French normally states it because verb endings alone are not always distinct.', examples: [{ french: 'Je suis français.', english: 'I am French.' }, { french: 'Nous sommes ici.', english: 'We are here.' }] },
  { id: '30000000-0000-0000-0000-000000000002', slug: 'etre-present', title: 'Être in the present tense', category: 'Verbs', summary: 'Être means “to be” and is irregular in the present.', full_explanation: 'Use être for identity, nationality, and descriptions. Its forms are je suis, tu es, il/elle/on est, nous sommes, vous êtes, ils/elles sont.', examples: [{ french: 'Je suis Marc.', english: 'I am Marc.' }, { french: 'Elle est française.', english: 'She is French.' }] },
  { id: '30000000-0000-0000-0000-000000000003', slug: 'cest-versus-il-est', title: "C'est vs il/elle est", category: 'Syntax', summary: "Use c'est before a noun or name; use il/elle est before an adjective or nationality.", full_explanation: "C'est introduces or identifies something. Il/elle est describes a known person or thing.", examples: [{ french: "C'est Marc.", english: 'That is Marc.' }, { french: 'Il est français.', english: 'He is French.' }] },
  { id: '30000000-0000-0000-0000-000000000004', slug: 'numbers-and-age', title: 'Numbers and age', category: 'Syntax', summary: 'French uses avoir, not être, to say how old someone is.', full_explanation: 'Say j\'ai vingt ans literally “I have twenty years.” Numbers generally stay unchanged before a noun.', examples: [{ french: "J'ai dix-huit ans.", english: 'I am eighteen.' }, { french: 'Nous sommes trois.', english: 'There are three of us.' }] },
  { id: '30000000-0000-0000-0000-000000000005', slug: 'articles-partitives', title: 'Articles for food and drink', category: 'Nouns', summary: 'Use un/une for one countable item and du/de la for an unspecified amount.', full_explanation: 'French articles carry gender and number. After vouloir or prendre, food often uses un/une for a unit and du/de la for an amount.', examples: [{ french: 'Je prends un café.', english: 'I am having a coffee.' }, { french: "Elle veut de l'eau.", english: 'She wants water.' }] },
  { id: '30000000-0000-0000-0000-000000000006', slug: 'er-present', title: 'Regular -ER verbs in the present', category: 'Verbs', summary: 'Remove -er and add -e, -es, -e, -ons, -ez, -ent.', full_explanation: 'Most French verbs follow this pattern. The -ent ending for ils/elles is normally silent.', examples: [{ french: "Je paie l'addition.", english: 'I pay the bill.' }, { french: 'Ils parlent français.', english: 'They speak French.' }] },
  { id: '30000000-0000-0000-0000-000000000007', slug: 'possessive-adjectives', title: 'Possessive adjectives: mon, ma, mes', category: 'Nouns', summary: 'Possessive adjectives agree with the noun possessed, not with the owner.', full_explanation: 'Use mon before masculine singular nouns, ma before feminine singular nouns, and mes before plural nouns.', examples: [{ french: 'Mon frère est petit.', english: 'My brother is small.' }, { french: 'Ma sœur est grande.', english: 'My sister is tall.' }] },
  { id: '30000000-0000-0000-0000-000000000008', slug: 'silent-final-consonants', title: 'Silent final consonants', category: 'Phonetics', summary: 'Many final consonants are silent in ordinary speech, but spelling still records them.', full_explanation: 'Final -s in plural nouns and the -ent ending of ils/elles verbs are usually silent. The interface marks silent segments visually.', examples: [{ french: 'Ils parlent.', english: 'They speak.' }, { french: 'Les cafés.', english: 'The cafés.' }] },
]
